package br.com.conectatea.profissional.domain; import jakarta.persistence.*; import java.time.*; @Entity @Table(name="tarefas_limpeza_arquivo") public class TarefaLimpezaArquivo{@Id @GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;private String chave;private String motivo;private int tentativas;@Column(name="proxima_tentativa_em")private Instant proxima=Instant.now();@Column(name="concluida_em")private Instant concluida;@Column(name="ultimo_erro")private String erro;@Column(name="criado_em")private Instant criada=Instant.now();protected TarefaLimpezaArquivo(){}public TarefaLimpezaArquivo(String k,String m){chave=k;motivo=m;}public Long getId(){return id;}public String getChave(){return chave;}public void falhar(String e){tentativas++;erro=e.length()>500?e.substring(0,500):e;proxima=Instant.now().plusSeconds(Math.min(3600,1L<<Math.min(tentativas,11)));}public void concluir(){concluida=Instant.now();}}
